    {target = 'pyrokinetic_flamethrower', traits = {'PYROKINETIC'}, prereqs = {{{'pyrokinetic_call_flames', 7}, {'pyrokinetic_flash', 5}}}, msg = 'Use of your powers has led to an insight.  Rather than focusing on a point, you could spew a swath of flames, damaging a whole group of enemies, if you can figure out the proper technique.'},
    {target = 'pyrokinetic_incineration', traits = {'PYROKINETIC'}, prereqs = {{{'pyrokinetic_eruption', 14}, {'pyrokinetic_blast', 10}, {'pyrokinetic_aoe_blast', 6}}, {{'pyrokinetic_flamethrower', 10}, {'pyrokinetic_blast', 10}, {'pyrokinetic_aoe_blast', 6}}}, msg = 'Use of your powers has led to an insight.  By focusing all of your power on a single point, you could raise the temperature there thousands of degrees, incinerating whatever you\'re focused on, if you can figure out the proper technique.'},
    {target = 'pyrokinetic_lance', traits = {'PYROKINETIC'}, prereqs = {{{'pyrokinetic_eruption', 9}, {'pyrokinetic_quell_flames', 6}}, {{'pyrokinetic_call_flames', 6}}}, msg = 'Use of your powers has led to an insight.  You could focus your heat into a searing line, capable of welding or cutting through metal, if you can figure out the proper technique.'},
    {target = 'pyrokinetic_quell_flames', traits = {'PYROKINETIC'}, prereqs = {{{'pyrokinetic_call_flames', 5}, {'pyrokinetic_intensify_flames', 6}}}, msg = 'Use of your powers has led to an insight.  Just as you can start fires, you could also stop them, harmlessly dispersing the heat and dissipating existing flames, if you can figure out the proper technique.'},
    {target = 'pyrokinetic_thermogenesis', traits = {'PYROKINETIC'}, prereqs = {{{'pyrokinetic_call_flames', 10}, {'pyrokinetic_flash', 7}}, {{'pyrokinetic_call_flames', 10}, {'pyrokinetic_intensify_flames', 8}}, {{'pyrokinetic_cloak', 6}, {'pyrokinetic_flash', 7}}, {{'pyrokinetic_cloak', 6}, {'pyrokinetic_intensify_flames', 8}}}, msg = 'Use of your powers has led to an insight.  You could heat the air itself, making an entire room warm, if you can figure out the proper technique.'},
    {target = 'telekinetic_aegis', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_wave', 8}, {'telekinetic_momentum', 12}, {'telekinetic_shield', 7}}, {{'telekinetic_wave', 8}, {'telekinetic_strength', 8}, {'telekinetic_shield', 7}}, {{'telekinetic_slowfall', 9}, {'telekinetic_momentum', 12}, {'telekinetic_shield', 7}}, {{'telekinetic_slowfall', 9}, {'telekinetic_strength', 8}, {'telekinetic_shield', 7}}}, msg = 'Use of your powers has led to an insight.  You could take all the energy of a telekinetic shield and pour it into a single instant, forming a barrier strong enough to repel a ballistic missile, if you can figure out the proper technique.'},
    {target = 'telekinetic_earthshaker', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_explosion', 8}, {'telekinetic_move_large_weight', 5}}, {{'telekinetic_explosion', 8}, {'telekinetic_hammer', 9}}, {{'telekinetic_wave', 13}, {'telekinetic_move_large_weight', 5}}, {{'telekinetic_wave', 13}, {'telekinetic_hammer', 9}}}, msg = 'Use of your powers has led to an insight.  You could grab the very earth with your powers, shaking it and causing a minor local earthquake, if you can figure out the proper technique.'},
    {target = 'telekinetic_explosion', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_slam_down', 12}, {'telekinetic_push', 10}}, {{'telekinetic_slam_down', 12}, {'telekinetic_pull', 10}}, {{'telekinetic_hammer', 7}, {'telekinetic_push', 10}}, {{'telekinetic_hammer', 7}, {'telekinetic_pull', 10}}}, msg = 'Use of your powers has led to an insight.  Rather than striking a single point, you could create an explosion of telekinetic force, damaging an entire area, if you can figure out the proper technique.'},
    {target = 'telekinetic_hammer', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_wave', 4}, {'telekinetic_slam_down', 6}}, {{'telekinetic_push', 8}, {'telekinetic_slam_down', 6}}}, msg = 'Use of your powers has led to an insight.  You could concentrate your application of force into a blunt instrument, shattering bones and splintering furniture, if you can figure out the proper technique.'},
    {target = 'telekinetic_levitation', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_push', 12}, {'telekinetic_slowfall', 9}}, {{'telekinetic_slowfall', 9}}}, msg = 'Use of your powers has led to an insight.  Rather than simply slowing your fall, you could stop it, completely defying gravity and walking on air, if you can figure out the proper technique.'},
    {target = 'telekinetic_lifting_field', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_vehicle_lift', 3}}, {{'telekinetic_pull', 7}, {'telekinetic_momentum', 5}}}, msg = 'Use of your powers has led to an insight.  You could wrap a field of telekinetic force around yourself to bear the weight of what you carry, if you can figure out the proper technique.'},
    {target = 'telekinetic_momentum', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_push', 5}, {'telekinetic_pull', 5}}}, msg = 'Use of your powers has led to an insight.  Instead of just applying all of your force at once, you could apply it gradually to all movement around you, making yourself slightly faster and anything dangerous slightly slower, if you can figure out the proper technique.'},
    {target = 'telekinetic_move_large_weight', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_push', 15}, {'telekinetic_momentum', 10}}, {{'telekinetic_push', 15}, {'telekinetic_vehicle_lift', 6}}, {{'telekinetic_pull', 15}, {'telekinetic_momentum', 10}}, {{'telekinetic_pull', 15}, {'telekinetic_vehicle_lift', 6}}}, msg = 'Use of your powers has led to an insight.  You could lift truly enormous amounts of weight, hurling huge creatures with a moment of effort, if you can figure out the proper technique.'},
    {target = 'telekinetic_noise', traits = {'TELEKINETIC'}, prereqs = {}, msg = 'Use of your powers has led to an insight.  You could use a quick burst of telekinetic force to create noise, luring enemies away from you or toward a trapped location, if you can figure out the proper technique.'},
    {target = 'telekinetic_shield', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_wave', 8}, {'telekinetic_momentum', 10}}}, msg = 'Use of your powers has led to an insight.  You could create a barrier of force around yourself, shielding you from harm, if you can figure out the proper technique.'},
    {target = 'telekinetic_slam_down', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_push', 4}}, {{'telekinetic_noise', 1}}}, msg = 'Use of your powers has led to an insight.  Instead of just shoving someone away from your location, you could direct the force orthogonally to knock someone to the ground, if you can figure out the proper technique.'},
    {target = 'telekinetic_slowfall', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_momentum', 6}}}, msg = 'Use of your powers has led to an insight.  You could lift yourself just a little, slowing you any time you take a fall and making swimming much easier, if you can figure out the proper technique.'},
    {target = 'telekinetic_strength', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_pull', 6}, {'telekinetic_momentum', 5}}, {{'telekinetic_push', 6}, {'telekinetic_momentum', 5}}}, msg = 'Use of your powers has led to an insight.  You could enhance your own strength, allowing you to pull much heavier objects or smash through study doors and walls, if you can figure out the proper technique.'},
    {target = 'telekinetic_vehicle_lift', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_pull', 8}, {'telekinetic_slowfall', 8}}, {{'telekinetic_strength', 10}}, {}}, msg = 'Use of your powers has led to an insight.  Rather than smashing objects with your telekinetic strength, you could apply it to lifting a car, allowing you to work on the undercarriage without a jack, if you can figure out the proper technique.'},
    {target = 'telekinetic_wave', traits = {'TELEKINETIC'}, prereqs = {{{'telekinetic_push', 7}, {'telekinetic_slam_down', 4}}}, msg = 'Use of your powers has led to an insight.  You could release force in all directions, knocking back everyone surrounding you all at once, if you can figure out the proper technique.'},
    {target = 'telepathic_animal_mind_control', traits = {'TELEPATH'}, prereqs = {{{'telepathic_morale', 8}}}, msg = 'Use of your powers has led to an insight.  The minds of animals are less complex than those of humans.  You should be able to overshadow them, to direct their actions and make them friendly toward you, if you can figure out the proper technique.'},
    {target = 'telepathic_beast_taming', traits = {'TELEPATH'}, prereqs = {{{'telepathic_animal_mind_control', 10}}}, msg = 'Use of your powers has led to an insight.  You can overshadow animal minds for a short time, but it shouldn\'t be difficult to make further adjustments, to make the animal friendly for weeks or months, if you can figure out the proper technique.'},
    {target = 'telepathic_blast', traits = {'TELEPATH'}, prereqs = {{{'telepathic_mind_sense', 7}, {'telepathic_morale', 4}}}, msg = 'Use of your powers has led to an insight.  Rather than any kind of subtle detection or adjustment, you could lash out with your powers, damaging the minds you contact, if you can figure out the proper technique.'},
    {target = 'telepathic_blast_radius', traits = {'TELEPATH'}, prereqs = {{{'telepathic_blast', 11}, {'telepathic_shield', 5}}, {{'telepathic_fear', 7}, {'telepathic_shield', 5}}}, msg = 'Use of your powers has led to an insight.  You could erase yourself from a target\'s perceptions, making them completely unable to even know that you\'re there, if you can figure out the proper technique.'},
    {target = 'telepathic_confusion', traits = {'TELEPATH'}, prereqs = {{{'telepathic_blast', 6}, {'telepathic_morale', 4}}, {{'telepathic_morale', 6}, {'telepathic_morale', 4}}}, msg = 'Use of your powers has led to an insight.  Rather than a clumsy hammer, you could use a telepathic scalpel to cut off the target\'s connection between their senses and their brain, leaving them stumbling and blind, if you can figure out the proper technique.'},
    {target = 'telepathic_fear', traits = {'TELEPATH'}, prereqs = {{{'telepathic_blast', 8}, {'telepathic_morale', 8}}}, msg = 'Use of your powers has led to an insight.  You could evoke your target\'s darkest fears, leaving them frozen in panic or trembling in terror, if you can figure out the proper technique.'},
    {target = 'telepathic_invisibility', traits = {'TELEPATH'}, prereqs = {{{'telepathic_confusion', 8}, {'telepathic_morale', 6}}, {{'telepathic_confusion', 8}, {'telepathic_blast', 11}}, {{'telepathic_confusion', 8}, {'telepathic_shield', 8}}}, msg = 'Use of your powers has led to an insight.  You could erase yourself from a target\'s perceptions, making them completely unable to even know that you\'re there, if you can figure out the proper technique.'},
    {target = 'telepathic_mesmerize', traits = {'TELEPATH'}, prereqs = {{{'telepathic_mind_sense', 6}}}, msg = 'Use of your powers has led to an insight.  You could nudge someone\'s mind into a self-focused spiral, keeping them in a daze and unaware of the outside world, if you can figure out the proper technique.'},
    {target = 'telepathic_mind_control', traits = {'TELEPATH'}, prereqs = {{{'telepathic_morale', 12}, {'telepathic_fear', 5}}, {{'telepathic_morale', 12}, {'telepathic_animal_mind_control', 8}}, {{'telepathic_morale', 12}, {'telepathic_confusion', 7}}, {{'telepathic_invisibility', 6}, {'telepathic_fear', 5}}, {{'telepathic_invisibility', 6}, {'telepathic_animal_mind_control', 8}}, {{'telepathic_invisibility', 6}, {'telepathic_confusion', 7}}}, msg = 'Use of your powers has led to an insight.  Just as you can control the minds of animals, you could control the minds of humans, or maybe even aliens, if you can figure out the proper technique.'},
    {target = 'telepathic_morale', traits = {'TELEPATH'}, prereqs = {{{'telepathic_concentration', 6}, {'telepathic_mind_sense', 5}}}, msg = 'Use of your powers has led to an insight.  In the same way you prepare your mind for learning, you could buffer it against the stresses of post-Cataclysmic life, editing out unwarranted negative thoughts, if you can figure out the proper technique.'},
    {target = 'telepathic_network', traits = {'TELEPATH'}, prereqs = {{{'telepathic_mind_sense', 10}, {'telepathic_blast_radius', 6}, {'telepathic_morale', 12}}, {{'telepathic_mind_sense', 10}, {'telepathic_blast_radius', 6}, {'telepathic_invisibility', 6}}}, msg = 'Use of your powers has led to an insight.  Thought is far faster than speech, and with your allies nearby you could warn each other of any dangers or enemy weaknesses as fast as thinking, if you can figure out the proper technique.'},
    {target = 'telepathic_shield', traits = {'TELEPATH'}, prereqs = {{{'telepathic_concentration', 5}}}, msg = 'Use of your powers has led to an insight.  You could invert the extreme focus of the concentration trance to make an impenetrable shell around your mind, protecting you from telepathic attack, if you can figure out the proper technique.'},
    {target = 'teleport_banish', traits = {'TELEPORTER'}, prereqs = {{{'teleport_farstep', 6}, {'teleport_displacement', 10}}, {{'teleport_collapse', 8}, {'teleport_displacement', 10}}, {{'teleport_transpose', 8}, {'teleport_displacement', 10}}}, msg = 'Use of your powers has led to an insight.  You could send your target somewhere *else*, some other place far from you in the endless parade of realities, if you can figure out the technique.'},
    {target = 'teleport_collapse', traits = {'TELEPORTER'}, prereqs = {{{'teleport_slow', 10}, {'teleport_stride', 4}}, {{'teleport_transpose', 6}, {'teleport_stride', 4}}}, msg = 'Use of your powers has led to an insight.  You could warp space to such a degree that you could redirect your targets\' movement, forcing them to travel toward a central point regardless of their intent, if you can figure out the technique.'},
    {target = 'teleport_dilated_gateway', traits = {'TELEPORTER'}, prereqs = {{{'teleport_gateway', 8}, {'teleport_banish', 2}}}, msg = 'Use of your powers has led to an insight.  Just as you can teleport yourself to memorized locations, you can also teleport other beings to those same locations alongside you.'},
    {target = 'teleport_displacement', traits = {'TELEPORTER'}, prereqs = {{{'teleport_item_apport', 5}, {'teleport_slow', 10}}}, msg = 'Use of your powers has led to an insight.  You could teleport only your target, sending them somewhere nearby away from you, if you can figure out the technique.'},
    {target = 'teleport_farstep', traits = {'TELEPORTER'}, prereqs = {{{'teleport_stride', 8}, {'teleport_phase', 10}}, {{'teleport_collapse', 6}, {'teleport_phase', 10}}}, msg = 'Use of your powers has led to an insight.  You could travel much further distances, crossing dozens of meters in moments, if you can figure out the technique.'},
    {target = 'teleport_gateway', traits = {'TELEPORTER'}, prereqs = {{{'teleport_loci_establishment', 6}, {'teleport_farstep', 10}}}, msg = 'Use of your powers has led to an insight.  Once you properly study a location so you\'re familiar enough with it, you could return there in moments even if you\'re fifty miles away, if you can figure out the technique.'},
    {target = 'teleport_item_apport', traits = {'TELEPORTER'}, prereqs = {{{'teleport_blink', 4}, {'teleport_slow', 4}}}, msg = 'Use of your powers has led to an insight.  Rather than traveling to a new location yourself, you could send an item you were holding there, if you can figure out the proper technique.'},
    {target = 'teleport_loci_establishment', traits = {'TELEPORTER'}, prereqs = {{{'teleport_stride', 6}, {'teleport_farstep', 6}}}, msg = 'Use of your powers has led to an insight.  You could concentrate on a specific location and teleport there at will.', also = {'teleport_loci_technique'}},
    {target = 'teleport_phase', traits = {'TELEPORTER'}, prereqs = {{{'teleport_blink', 6}}}, msg = 'Use of your powers has led to an insight.  You could control your teleporting, traveling short distances without crossing the intervening space, if you can figure out the proper technique.'},
    {target = 'teleport_reactive_displacement', traits = {'TELEPORTER'}, prereqs = {{{'teleport_displacement', 5}}}, msg = 'Use of your powers has led to an insight.  You could automatically teleport away attacking enemies, if you can figure out the technique.'},
    {target = 'teleport_reality_tear', traits = {'TELEPORTER'}, prereqs = {{{'teleport_summon', 10}, {'teleport_gateway', 10}}}, msg = 'Use of your powers has led to an insight.  You are able to open a permanent tear in reality to the Nether, allowing all manners of creatures to pass through to Earth.'},
    {target = 'teleport_relocation', traits = {'TELEPORTER'}, prereqs = {{{'teleport_gateway', 8}, {'teleport_item_apport', 6}}}, msg = 'Use of your powers has led to an insight.  Just as you can teleport yourself to memorized locations, you can also teleport held items to those same locations.'},
    {target = 'teleport_stride', traits = {'TELEPORTER'}, prereqs = {{{'teleport_phase', 4}, {'teleport_slow', 6}}}, msg = 'Use of your powers has led to an insight.  Rather than expanding space, you could collapse it, making each of your steps cover a larger area of ground despite not moving any more quickly, if you can figure out the proper technique.'},
    {target = 'teleport_summon', traits = {'TELEPORTER'}, prereqs = {{{'teleport_displacement', 12}, {'teleport_gateway', 6}}, {{'teleport_banish', 7}, {'teleport_gateway', 6}}}, msg = 'Use of your powers has led to an insight.  Just as you can send a target away from you, you could open up a portal to the Nether and allow some of its denizens to come through to Earth, if you can figure out the technique.'},
    {target = 'teleport_transpose', traits = {'TELEPORTER'}, prereqs = {{{'teleport_displacement', 5}, {'teleport_stride', 5}}}, msg = 'Use of your powers has led to an insight.  You could combine moving yourself and moving a target to swap places, moving them to your previous location while you take their place, if you can figure out the technique.'},
    {target = 'teleport_warped_strikes', traits = {'TELEPORTER'}, prereqs = {{{'teleport_item_apport', 6}, {'teleport_stride', 10}}}, msg = 'Use of your powers has led to an insight.  You can maintain an easily modifiable section of warped space around you, which you can warp to allow your attacks to reach much further than they should.'},
  }
end
